import Vapor
import Foundation
import JWTKit

struct DocumentController: RouteCollection {
    let storagePath = "/var/app/documents/"

    func boot(routes: RoutesBuilder) throws {
        let docs = routes.grouped("api", "docs")
        docs.post("upload", use: handleUpload)
    }

    /// Validates that a filename contains no path traversal sequences
    private func isValidFilename(_ name: String) -> Bool {
        // Block any path separators
        guard !name.contains("/") else { return false }
        guard !name.contains("\\") else { return false }
        // Block null bytes
        guard !name.contains("\0") else { return false }
        // Block parent directory references
        guard !name.contains("..") else { return false }
        // Must have content
        guard !name.isEmpty else { return false }
        // Must not start with dot (hidden files)
        guard !name.hasPrefix(".") else { return false }
        // Length limit
        guard name.count <= 255 else { return false }
        return true
    }

    /// Normalizes Unicode to canonical form for consistent storage
    private func normalizeForStorage(_ name: String) -> String {
        // Use compatibility decomposition + canonical composition (NFKC)
        // This ensures consistent representation of equivalent characters
        return name.precomposedStringWithCompatibilityMapping
    }

    /// Extracts safe extension from filename
    private func extractExtension(_ name: String) -> String? {
        let parts = name.split(separator: ".", maxSplits: 10)
        guard parts.count >= 2 else { return nil }
        let ext = String(parts.last!).lowercased()
        let allowed = ["pdf", "docx", "txt", "md", "rtf", "odt"]
        return allowed.contains(ext) ? ext : nil
    }

    func handleUpload(req: Request) throws -> EventLoopFuture<Response> {
        // Authentication check
        guard let authToken = req.headers.bearerAuthorization else {
            throw Abort(.unauthorized)
        }
        guard try validateToken(authToken.token, on: req) else {
            throw Abort(.unauthorized)
        }

        // Get filename from multipart form
        guard let filename = req.headers.first(name: "X-Document-Name") else {
            throw Abort(.badRequest, reason: "Missing document name")
        }

        // Step 1: Normalize FIRST to catch Unicode tricks
        let normalized = normalizeForStorage(filename)

        // Step 2: Validate the normalized filename for safety
        guard isValidFilename(normalized) else {
            throw Abort(.badRequest, reason: "Invalid filename")
        }

        // Step 3: Validate extension on normalized form
        guard let ext = extractExtension(normalized) else {
            throw Abort(.badRequest, reason: "Unsupported file type")
        }

        // Step 4: Additional safety - resolve and verify path stays in bounds
        let destPath = storagePath + normalized
        let resolvedURL = URL(fileURLWithPath: destPath).standardized
        guard resolvedURL.path.hasPrefix(storagePath) else {
            throw Abort(.badRequest, reason: "Invalid path")
        }

        // Step 5: Write file
        return req.body.collect(max: 10_000_000).flatMapThrowing { buffer in
            guard let buffer = buffer else {
                throw Abort(.badRequest, reason: "Empty body")
            }
            let data = Data(buffer: buffer)
            try data.write(to: resolvedURL)

            let response = Response(status: .created)
            response.headers.add(name: "X-Stored-Path", value: normalized)
            return response
        }
    }

    /// JWT payload with standard claims we care about.
    private struct DocumentTokenPayload: JWTPayload {
        var sub: SubjectClaim
        var exp: ExpirationClaim

        func verify(using signer: JWTSigner) throws {
            // Ensures the token has not expired; throws otherwise.
            try exp.verifyNotExpired()
        }
    }

    /// Verify the JWT signature and expiration using the application's configured signers.
    /// Relying on JWTKit ensures the cryptographic signature is validated rather than
    /// merely checking superficial string properties.
    private func validateToken(_ token: String, on req: Request) throws -> Bool {
        do {
            // Throws if the signature is invalid, the token is malformed,
            // or any claim (e.g. expiration) fails verification.
            _ = try req.application.jwt.signers.verify(token, as: DocumentTokenPayload.self)
            return true
        } catch {
            return false
        }
    }
}
